'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),vm=require('node:vm');
const catalogs=JSON.parse(fs.readFileSync(path.join(__dirname,'../static/ui-messages.json'),'utf8'));
let locale='en';const nodes={},listeners={},calls=[];
for(const id of ['backupCheckResult-PHONE','backupCheckStart-PHONE','backupCheckCancel-PHONE'])nodes[id]={textContent:'',disabled:false,classList:{toggle(name,hidden){this.hidden=hidden;}},removeAttribute(){}};
const document={getElementById(id){return nodes[id];},addEventListener(name,fn){listeners[name]=fn;}};
const window={document,addEventListener(name,fn){listeners[name]=fn;},IOSBKI18n:{t(key,params={}){return (catalogs[locale][key]||key).replace(/\{(\w+)\}/g,(_,key)=>String(params[key]));},has(key){return key in catalogs[locale];},formatDate(value){return value;}},csrfFetch(url,options){calls.push({url,body:JSON.parse(options.body)});return Promise.resolve({ok:true,json:()=>Promise.resolve({id:'bkp-000000000001'})});},refreshBackupControlStatus(){return Promise.resolve();}};
vm.runInNewContext(fs.readFileSync(path.join(__dirname,'../static/backup-checks.js'),'utf8'),{window});
const api=window.IOSBKChecks;
const check={id:'bkp-000000000001',kind:'manifest',state:'unavailable',reason:'encrypted_manifest',metadata_complete:true,manifest_complete:false,records_checked:0,objects_checked:0,freshness:'current'};
api.render({udid:'PHONE',backing_up:true,backup_check_active:true,backup_check:check});
assert.equal(nodes['backupCheckStart-PHONE'].disabled,true);
assert.equal(nodes['backupCheckCancel-PHONE'].classList.hidden,false);
assert.match(nodes['backupCheckResult-PHONE'].textContent,/Encrypted manifest/);
assert.match(nodes['backupCheckResult-PHONE'].textContent,/manifest scan complete: No/);
const cancelled=api.summary({...check,reason:'cancelled',last_completed:{...check,state:'passed',reason:'',completed_at:'2026-10-30T12:00:00Z'}});
assert.match(cancelled,/cancelled/i);
assert.match(cancelled,/Previous completed check/);
assert.match(cancelled,/2026-10-30T12:00:00Z/);
locale='zh-CN';listeners['iosbk:localechange']();
assert.match(nodes['backupCheckResult-PHONE'].textContent,/加密清单/);
assert.match(api.summary({...check,state:'passed',reason:'',freshness:'stale'}),/已过期/);
listeners.click({target:{closest(){return {dataset:{udid:'PHONE',checkAction:'cancel'}};}}});
assert.equal(calls.length,1);assert.equal(calls[0].body.id,check.id);
listeners.click({target:{closest(){return {dataset:{udid:'PHONE',checkAction:'cancel'}};}}});
assert.equal(calls.length,1,'in-flight cancellation is deduplicated');
console.log('backup checks preserve coverage, stale evidence, language and cancellation identity');
